component.css:
.mld {--ink: #2a3440;--dim: #6b7480;--panel: #f8f0de;--acc: #2d5680;position: relative;width: 100%;aspect-ratio: 1672 / 941;container-type: size;overflow: hidden;border-radius: 10px;background: #0d1420;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;}
.mld *, .mld *::before, .mld *::after { box-sizing: border-box; }
.mld button { font-family: inherit; border: 0; background: none; padding: 0; margin: 0; cursor: pointer; color: inherit; text-align: left; }
.mld button:focus { outline: none; }
.mld button:focus-visible { outline: 2px solid #4e86b4; outline-offset: 1px; }
.mld-bg { position: absolute; inset: 0; background: url("https://origin.picgo.net/2026/10/11/100008601956a9163bf72203e4.png") center / 100% 100% no-repeat; pointer-events: none; }
.mld-slots, .mld-pager { position: absolute; inset: 0; }
.mld-slot {position: absolute; width: 22.7%; height: 22.7%;border-radius: 6px;overflow: hidden;transition: box-shadow .15s;}
@media (hover: hover) {.mld-slot:not(.is-empty):hover { box-shadow: inset 0 0 0 2px #2d56809c; }}
.mld-slot__in {position: absolute; inset: 7% 8% 6%;display: flex; flex-direction: column; justify-content: space-between;color: var(--ink);}
.mld-slot__top { display: flex; align-items: baseline; gap: 2%; font-size: 1.55cqh; color: var(--dim); }
.mld-slot__top b { font-size: 1.9cqh; color: var(--acc); letter-spacing: .05em; }
.mld-slot__loc {font-size: 2.35cqh; font-weight: 700; color: var(--ink);letter-spacing: .04em;overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
.mld-slot__sub { display: flex; align-items: baseline; gap: 5%; font-size: 1.5cqh; color: var(--dim); }
.mld-slot__sub b { color: #8a5a28; font-weight: 700; }
.mld-slot__scene {font-size: 1.45cqh; line-height: 1.4; color: #4d5661;display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;}
.mld-slot.is-empty { cursor: default; }
.mld-pager__btn {position: absolute; top: 80%; height: 10%; display: flex; align-items: center; justify-content: center;font-size: 2.6cqh; color: var(--ink); border-radius: 4px;}
.mld-pager__btn--num { width: 6.5%; }
.mld-pager__btn--num.is-cur { color: var(--acc); font-weight: 800; text-decoration: underline; text-underline-offset: .5cqh; }
@media (hover: hover) {.mld-pager__btn:hover { background: #2d568024; }}
#mldBack { position: absolute; left: 1.5%; top: 91.8%; width: 11.5%; height: 5.5%; border-radius: 6px; }
@media (hover: hover) {#mldBack:hover { background: #2d56803d; box-shadow: inset 0 0 0 2px #4e86b480; }}
